typedef struct { int present; int value; } int_opt;

/* no Functor: one function per payload type, structure kept by hand */
static int_opt int_opt_map(int_opt o, int (*f)(int)) {
    if (!o.present) return o;          /* the empty case IS the instance */
    return (int_opt){ 1, f(o.value) };
}

/* the type-erased version is worse than the branch it replaces:
   void *(*)(void *) erases the payload type and any chance of a check */
